function mdl = build_enr312_simulink(outDir)
%BUILD_ENR312_SIMULINK  Generate the Simulink model enr312_pendulum.slx.
%
%   build_enr312_simulink()            writes matlab/simulink/enr312_pendulum.slx
%
%   The model is generated by this script, so it can be rebuilt, reviewed and
%   versioned like code. It contains:
%     Controller   discrete (500 Hz / div), the firmware's arithmetic for the LQR of
%                  experiments 23/24 and the dual PID of Tutorial 6
%                  (firmware/enr312/src/enr312_ctrl.c): filtered derivatives, the
%                  plant-input clamp, anti-windup
%     Arm          the runner: the arm velocity is the integral of u, limited to vMax
%     Pendulum     the nonlinear rigid pendulum on a rotating arm
%                  psi'' = -wg2 sin psi + wr2 cos psi theta'' + theta'^2 sin psi cos psi
%                          - gamma psi' - c tanh(psi'/w) + tap
%     Sensors      the encoder (0.15 deg) and the microstep count (0.1125 deg)
%   Parameters come from the workspace struct P (enr312_simulink_params). Run it
%   with run_enr312_simulink, or open it and press Run after
%   P = enr312_simulink_params();
    here = fileparts(mfilename('fullpath'));
    if nargin < 1, outDir = here; end
    mdl = 'enr312_pendulum';
    if bdIsLoaded(mdl), close_system(mdl, 0); end
    new_system(mdl); load_system(mdl);
    set_param(mdl, 'Solver', 'ode45', 'MaxStep', '1e-3', 'RelTol', '1e-6', 'StopTime', 'P.stopTime', ...
        'SaveOutput', 'off', 'SaveTime', 'off', 'ReturnWorkspaceOutputs', 'on');
    add = @(src, name, pos, varargin) add_block(src, [mdl '/' name], 'Position', pos, varargin{:});
    ln = @(a, b) add_line(mdl, a, b, 'autorouting', 'smart');

    % ---- controller (discrete) ----------------------------------------------------
    add('simulink/User-Defined Functions/MATLAB Function', 'Controller', [420 60 560 180]);
    setCode([mdl '/Controller'], controllerCode(), 'P.Ts*P.div');
    % ---- arm: u (deg/s^2) -> velocity (limited) -> angle --------------------------------
    add('simulink/Math Operations/Gain', 'deg2rad u', [600 105 650 135], 'Gain', 'pi/180');
    add('simulink/Continuous/Integrator', 'arm velocity', [690 100 730 140], ...
        'LimitOutput', 'on', 'UpperSaturationLimit', 'P.vMax*pi/180', 'LowerSaturationLimit', '-P.vMax*pi/180');
    add('simulink/Continuous/Integrator', 'arm angle', [780 100 820 140]);
    % ---- pendulum (continuous) ------------------------------------------------------
    add('simulink/User-Defined Functions/MATLAB Function', 'Pendulum dynamics', [690 230 830 350]);
    setCode([mdl '/Pendulum dynamics'], plantCode(), '');
    add('simulink/Continuous/Integrator', 'pendulum rate', [880 260 920 300]);
    add('simulink/Continuous/Integrator', 'pendulum angle', [960 260 1000 300], ...
        'InitialCondition', 'P.upright*pi + (1 - 2*P.upright)*P.alpha0*pi/180');
    % tap: a short pulse of angular acceleration that adds P.tapRate deg/s
    add('simulink/Sources/Clock', 'clock', [560 300 580 320]);
    add('simulink/User-Defined Functions/MATLAB Function', 'Tap', [600 290 660 330]);
    setCode([mdl '/Tap'], tapCode(), '');
    % ---- sensors -----------------------------------------------------------------------
    add('simulink/Math Operations/Gain', 'rad2deg arm', [870 105 910 135], 'Gain', '180/pi');
    add('simulink/Discontinuities/Quantizer', 'microsteps', [950 105 990 135], 'QuantizationInterval', 'P.stepDeg');
    add('simulink/Math Operations/Gain', 'rad2deg pend', [1040 265 1080 295], 'Gain', '180/pi');
    add('simulink/Discontinuities/Quantizer', 'encoder', [1110 265 1150 295], 'QuantizationInterval', 'P.encDeg');
    add('simulink/Math Operations/Gain', 'rad2deg rate', [760 160 800 190], 'Gain', '180/pi');
    % ---- logging -----------------------------------------------------------------------
    names = {'theta_deg', 'psi_deg', 'u'}; pos = {[1040 40 1100 70], [1200 200 1260 230], [600 20 660 50]};
    for i = 1:3
        add('simulink/Sinks/To Workspace', ['log ' names{i}], pos{i}, 'VariableName', names{i}, 'SaveFormat', 'Timeseries');
    end
    % ---- wiring --------------------------------------------------------------------------
    ln('Controller/1', 'deg2rad u/1');
    ln('deg2rad u/1', 'arm velocity/1');
    ln('arm velocity/1', 'arm angle/1');
    ln('arm angle/1', 'rad2deg arm/1');
    ln('rad2deg arm/1', 'microsteps/1');
    ln('microsteps/1', 'Controller/1');
    ln('arm velocity/1', 'rad2deg rate/1');
    ln('rad2deg rate/1', 'Controller/2');
    ln('encoder/1', 'Controller/3');
    ln('pendulum angle/1', 'rad2deg pend/1');
    ln('rad2deg pend/1', 'encoder/1');
    ln('pendulum angle/1', 'Pendulum dynamics/1');
    ln('pendulum rate/1', 'Pendulum dynamics/2');
    ln('arm velocity/1', 'Pendulum dynamics/3');
    ln('deg2rad u/1', 'Pendulum dynamics/4');
    ln('clock/1', 'Tap/1');
    ln('Tap/1', 'Pendulum dynamics/5');
    ln('Pendulum dynamics/1', 'pendulum rate/1');
    ln('pendulum rate/1', 'pendulum angle/1');
    ln('microsteps/1', 'log theta_deg/1');
    ln('rad2deg pend/1', 'log psi_deg/1');
    ln('Controller/1', 'log u/1');
    % scopes, for running the model by hand (Run button); they do not affect the results
    add('simulink/Sinks/Scope', 'Scope arm theta, pendulum psi', [1320 120 1360 180], 'NumInputPorts', '2');
    add('simulink/Sinks/Scope', 'Scope input u', [700 0 740 40]);
    ln('microsteps/1', 'Scope arm theta, pendulum psi/1');
    ln('encoder/1', 'Scope arm theta, pendulum psi/2');
    ln('Controller/1', 'Scope input u/1');
    add_block('built-in/Note', [mdl '/note'], 'Position', [420 420], 'Text', ...
        ['ENR312 rotary inverted pendulum. Generated by build_enr312_simulink.m. ' ...
         'Set P = enr312_simulink_params(...) first. Plant in rad, controller in deg (as the firmware).']);
    file = fullfile(outDir, [mdl '.slx']);
    save_system(mdl, file); close_system(mdl, 0);
    fprintf('wrote %s\n', file);
end

function setCode(blk, code, sampleTime)
% put the code into a MATLAB Function block and declare P a parameter
    rt = sfroot; ch = rt.find('-isa', 'Stateflow.EMChart', 'Path', blk);
    ch.Script = code;
    d = ch.find('-isa', 'Stateflow.Data', 'Name', 'P');
    if ~isempty(d), d.Scope = 'Parameter'; d.Tunable = false; end
    if ~isempty(sampleTime), ch.ChartUpdate = 'DISCRETE'; ch.SampleTime = sampleTime; end
end

function s = controllerCode()
s = strjoin({
'function u = Controller(theta, thetadot, psi, P)'
'% The firmware''s control law (enr312_ctrl.c), deg units, one call per control period.'
'% theta: arm (microsteps, deg); thetadot: arm velocity (deg/s); psi: encoder (deg).'
'persistent dpsi psiPrev have er_prev dr ir ep_prev dp'
'if isempty(dpsi), dpsi = 0; psiPrev = 0; have = false; er_prev = 0; dr = 0; ir = 0; ep_prev = 0; dp = 0; end'
'dt = P.Ts * P.div;'
'if ~P.closedLoop, u = 0; return; end'
'a = mod(180 - psi + 180, 360) - 180;            % alpha: deviation from upright'
'if P.isLqr'
'    rawd = 0; if have, rawd = (psi - psiPrev) / dt; end'
'    dpsi = dpsi + lp(P.fdp, dt) * (rawd - dpsi); psiPrev = psi; have = true;'
'    adot = -dpsi;'
'    uu = -(P.k(1) * (theta - P.ref) + P.k(2) * thetadot) - (P.k(3) * a + P.k(4) * adot);'
'else'
'    er = P.ref - theta;'
'    der = 0; if have, der = (er - er_prev) / dt; end'
'    dr = dr + lp(P.fdr, dt) * (der - dr); er_prev = er;'
'    ur = P.kp * er + P.kd * dr + ir;'
'    ep = -a;'
'    dep = 0; if have, dep = (ep - ep_prev) / dt; end'
'    dp = dp + lp(P.fdp, dt) * (dep - dp); ep_prev = ep; have = true;'
'    up = P.kpp * ep + P.kdp * dp;'
'    uu = -ur + up;                               % inverted: the rotor loop sign flips'
'    if P.ki > 0 && abs(uu) < P.uLimit'
'        ir = min(max(ir + P.ki * er * dt, -P.uLimit), P.uLimit);'
'    end'
'end'
'u = min(max(uu, -P.uLimit), P.uLimit);'
'end'
''
'function k = lp(fc, dt)'
'k = 1 - exp(-2 * pi * fc * dt); k = min(max(k, 0), 1);'
'end'}, newline);
end

function s = plantCode()
s = strjoin({
'function psiddot = Pendulum_dynamics(psi, psidot, thetadot, thetaddot, tap, P)'
'% rigid pendulum on a rotating arm (docs/first_principles/ROTARY_PENDULUM_DYNAMICS.md, eq. 6)'
'% plus dry pivot friction, smoothed as c*tanh(psidot/w); all in rad.'
'psiddot = -P.wg2 * sin(psi) + P.wr2 * cos(psi) * thetaddot + thetadot^2 * sin(psi) * cos(psi) ...'
'          - P.gamma * psidot - P.coulomb * tanh(psidot / P.coulombWidth) + tap;'
'end'}, newline);
end

function s = tapCode()
s = strjoin({
'function a = Tap(t, P)'
'% a tap: P.tapRate deg/s added to the pendulum rate, spread over P.tapWidth s.'
'% The rate is given in alpha (from upright), and alpha = 180 deg - psi.'
'a = 0;'
'if P.tapRate ~= 0 && t >= P.tapTime && t < P.tapTime + P.tapWidth'
'    a = -P.tapRate * pi / 180 / P.tapWidth;'
'end'
'end'}, newline);
end
